#!/usr/bin/env bun
/**
 * CLI front-end for the artifact cleanup planner.
 *
 * Reads a JSON fixture describing artifacts (and optionally an embedded
 * policy), applies retention policies (overridable via flags / env vars), and
 * prints a human-readable deletion plan plus machine-parseable summary lines.
 *
 * Usage:
 *   bun run app.ts --input artifacts.json [--max-age-days N]
 *       [--max-total-size BYTES] [--keep-latest N] [--dry-run]
 *
 * The fixture file may be of the form:
 *   { "artifacts": [ ... ], "policy": { ... } }
 * or simply a bare array of artifacts: [ ... ]
 *
 * Flags / env vars take precedence over the embedded policy. Env vars:
 *   INPUT, MAX_AGE_DAYS, MAX_TOTAL_SIZE, KEEP_LATEST, DRY_RUN
 */

import {
  planCleanup,
  type Artifact,
  type RetentionPolicy,
  type CleanupPlan,
} from "./cleanup.ts";

interface ParsedArgs {
  input?: string;
  maxAgeDays?: number;
  maxTotalSize?: number;
  keepLatest?: number;
  dryRun: boolean;
}

/** Parse argv flags, falling back to environment variables. */
function parseArgs(argv: string[]): ParsedArgs {
  const env = process.env;
  const args: ParsedArgs = {
    input: env.INPUT,
    maxAgeDays: numOrUndef(env.MAX_AGE_DAYS),
    maxTotalSize: numOrUndef(env.MAX_TOTAL_SIZE),
    keepLatest: numOrUndef(env.KEEP_LATEST),
    dryRun: boolish(env.DRY_RUN),
  };

  for (let i = 0; i < argv.length; i++) {
    const flag = argv[i];
    const next = () => {
      const v = argv[++i];
      if (v === undefined) throw new Error(`Missing value for ${flag}`);
      return v;
    };
    switch (flag) {
      case "--input":
        args.input = next();
        break;
      case "--max-age-days":
        args.maxAgeDays = parseNum(next(), "--max-age-days");
        break;
      case "--max-total-size":
        args.maxTotalSize = parseNum(next(), "--max-total-size");
        break;
      case "--keep-latest":
        args.keepLatest = parseNum(next(), "--keep-latest");
        break;
      case "--dry-run":
        args.dryRun = true;
        break;
      default:
        throw new Error(`Unknown argument: ${flag}`);
    }
  }
  return args;
}

function numOrUndef(v: string | undefined): number | undefined {
  if (v === undefined || v === "") return undefined;
  return parseNum(v, "value");
}

function parseNum(v: string, context: string): number {
  const n = Number(v);
  if (!Number.isFinite(n)) {
    throw new Error(`Expected a number for ${context}, got "${v}".`);
  }
  return n;
}

function boolish(v: string | undefined): boolean {
  return v === "1" || v?.toLowerCase() === "true";
}

/** Load and validate the fixture file into artifacts + embedded policy. */
async function loadFixture(
  path: string,
): Promise<{ artifacts: Artifact[]; policy: RetentionPolicy }> {
  const file = Bun.file(path);
  if (!(await file.exists())) {
    throw new Error(`Input file not found: ${path}`);
  }
  let raw: unknown;
  try {
    raw = JSON.parse(await file.text());
  } catch (e) {
    throw new Error(`Failed to parse JSON in ${path}: ${(e as Error).message}`);
  }

  let artifacts: unknown;
  let policy: RetentionPolicy = {};
  if (Array.isArray(raw)) {
    artifacts = raw;
  } else if (raw && typeof raw === "object") {
    const obj = raw as Record<string, unknown>;
    artifacts = obj.artifacts;
    if (obj.policy && typeof obj.policy === "object") {
      policy = obj.policy as RetentionPolicy;
    }
  }
  if (!Array.isArray(artifacts)) {
    throw new Error(
      `Fixture ${path} must contain an "artifacts" array (or be a bare array).`,
    );
  }
  return { artifacts: artifacts as Artifact[], policy };
}

/** Render the plan to stdout in a verifiable, greppable format. */
function render(plan: CleanupPlan): void {
  const { summary } = plan;
  console.log("=== Artifact Cleanup Plan ===");
  console.log(`MODE: ${plan.dryRun ? "DRY-RUN" : "EXECUTE"}`);
  console.log("--- To Delete ---");
  if (plan.toDelete.length === 0) {
    console.log("(none)");
  } else {
    for (const d of plan.toDelete) {
      console.log(
        `DELETE ${d.artifact.name} bytes=${d.artifact.sizeBytes} reason=${d.reason}`,
      );
    }
  }
  console.log("--- To Retain ---");
  if (plan.toRetain.length === 0) {
    console.log("(none)");
  } else {
    for (const a of plan.toRetain) {
      console.log(`RETAIN ${a.name} bytes=${a.sizeBytes}`);
    }
  }
  // Machine-parseable summary lines for assertions.
  console.log("--- Summary ---");
  console.log(`SUMMARY total=${summary.totalArtifacts}`);
  console.log(`SUMMARY retained=${summary.retainedCount}`);
  console.log(`SUMMARY deleted=${summary.deletedCount}`);
  console.log(`SUMMARY bytesReclaimed=${summary.bytesReclaimed}`);
  console.log(`SUMMARY bytesRetained=${summary.bytesRetained}`);
  if (plan.dryRun) {
    console.log("NOTE: dry-run — no artifacts were actually deleted.");
  }
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));
  if (!args.input) {
    throw new Error("No input file provided. Use --input <file> or INPUT env.");
  }

  const { artifacts, policy: embedded } = await loadFixture(args.input);

  // Flags override embedded policy.
  const policy: RetentionPolicy = {
    maxAgeDays: args.maxAgeDays ?? embedded.maxAgeDays,
    maxTotalSizeBytes: args.maxTotalSize ?? embedded.maxTotalSizeBytes,
    keepLatestNPerWorkflow: args.keepLatest ?? embedded.keepLatestNPerWorkflow,
  };

  const plan = planCleanup(artifacts, policy, { dryRun: args.dryRun });
  render(plan);
}

// Run only when invoked directly (not when imported by tests).
if (import.meta.main) {
  main().catch((err) => {
    console.error(`ERROR: ${(err as Error).message}`);
    process.exit(1);
  });
}

export { parseArgs, loadFixture };

