#!/usr/bin/env bun
/**
 * Integration harness: runs the artifact-cleanup workflow through `act`
 * (nektos/act) for each test case and asserts on EXACT expected output.
 *
 * Per requirements, every test case executes through the GitHub Actions
 * pipeline (not the script directly). For each case we:
 *   1. Build an isolated temp git repo containing the project files + that
 *      case's fixture data (written to fixtures/artifacts.json).
 *   2. Run `act push --rm` and capture stdout+stderr.
 *   3. Append the output to act-result.txt (clearly delimited).
 *   4. Assert act exited 0, every job shows "Job succeeded", and the parsed
 *      plan output matches the known-good values for that fixture.
 *
 * Run with:  bun run act-harness.ts
 *
 * NOTE: This file is intentionally NOT named *.test.ts so that the in-CI
 * `bun test` step does not try to invoke act recursively inside act.
 */

import { mkdtempSync, writeFileSync, copyFileSync, mkdirSync, rmSync, appendFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const HERE = import.meta.dir;
const RESULT_FILE = join(HERE, "act-result.txt");

// Files that must be present in the isolated repo for the workflow to run.
const PROJECT_FILES = [
  "app.ts",
  "cleanup.ts",
  "cleanup.test.ts",
  "package.json",
  ".actrc",
];

interface ExpectedPlan {
  deleted: string[]; // artifact names, sorted
  retained: string[]; // artifact names, sorted
  total: number;
  deletedCount: number;
  retainedCount: number;
  bytesReclaimed: number;
  bytesRetained: number;
}

interface TestCase {
  name: string;
  fixture: unknown; // written to fixtures/artifacts.json
  expected: ExpectedPlan;
}

// The workflow pins NOW=2026-06-26T00:00:00Z, so all expectations below are
// computed relative to that instant.
const CASES: TestCase[] = [
  {
    name: "age+keep-latest: old CI builds pruned, newest-per-workflow kept",
    fixture: {
      policy: { maxAgeDays: 30, maxTotalSizeBytes: 100000000, keepLatestNPerWorkflow: 1 },
      artifacts: [
        { name: "ci-build-100", sizeBytes: 5000000, createdAt: "2026-01-10T08:00:00Z", workflowName: "ci", workflowRunId: 100 },
        { name: "ci-build-101", sizeBytes: 6000000, createdAt: "2026-03-15T08:00:00Z", workflowName: "ci", workflowRunId: 101 },
        { name: "ci-build-102", sizeBytes: 7000000, createdAt: "2026-06-25T08:00:00Z", workflowName: "ci", workflowRunId: 102 },
        { name: "release-v1", sizeBytes: 20000000, createdAt: "2026-02-01T08:00:00Z", workflowName: "release", workflowRunId: 200 },
        { name: "nightly-old", sizeBytes: 3000000, createdAt: "2026-01-05T08:00:00Z", workflowName: "nightly", workflowRunId: 300 },
      ],
    },
    // ci-build-100 & 101 are >30d old and not the newest CI artifact -> deleted.
    // ci-build-102 newest CI (protected), release-v1 newest release (protected),
    // nightly-old newest nightly (protected). Size cap not breached.
    expected: {
      deleted: ["ci-build-100", "ci-build-101"],
      retained: ["ci-build-102", "nightly-old", "release-v1"],
      total: 5,
      deletedCount: 2,
      retainedCount: 3,
      bytesReclaimed: 11000000,
      bytesRetained: 30000000,
    },
  },
  {
    name: "size-cap: oldest unprotected evicted to meet total-size budget",
    fixture: {
      policy: { maxTotalSizeBytes: 1500, keepLatestNPerWorkflow: 1 },
      artifacts: [
        { name: "a", sizeBytes: 1000, createdAt: "2026-06-01T00:00:00Z", workflowName: "ci", workflowRunId: 1 },
        { name: "b", sizeBytes: 1000, createdAt: "2026-06-10T00:00:00Z", workflowName: "ci", workflowRunId: 2 },
        { name: "c", sizeBytes: 1000, createdAt: "2026-06-20T00:00:00Z", workflowName: "ci", workflowRunId: 3 },
      ],
    },
    // No max age. keep-latest-1 protects "c" (newest). Total 3000 > 1500.
    // Evict oldest unprotected: "a" (1000) -> 2000, still >1500 -> "b" (1000)
    // -> 1000 <= 1500. Retain "c" only.
    expected: {
      deleted: ["a", "b"],
      retained: ["c"],
      total: 3,
      deletedCount: 2,
      retainedCount: 1,
      bytesReclaimed: 2000,
      bytesRetained: 1000,
    },
  },
];

/** Run a command, returning combined output and exit code. */
function run(cmd: string, cmdArgs: string[], cwd: string): { out: string; code: number } {
  const res = spawnSync(cmd, cmdArgs, { cwd, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  const out = `${res.stdout ?? ""}${res.stderr ?? ""}`;
  return { out, code: res.status ?? 1 };
}

/** Build an isolated git repo for a single test case. */
function setupRepo(testCase: TestCase): string {
  const dir = mkdtempSync(join(tmpdir(), "act-artifact-"));

  for (const f of PROJECT_FILES) {
    copyFileSync(join(HERE, f), join(dir, f));
  }
  mkdirSync(join(dir, ".github", "workflows"), { recursive: true });
  copyFileSync(
    join(HERE, ".github", "workflows", "artifact-cleanup-script.yml"),
    join(dir, ".github", "workflows", "artifact-cleanup-script.yml"),
  );
  mkdirSync(join(dir, "fixtures"), { recursive: true });
  writeFileSync(
    join(dir, "fixtures", "artifacts.json"),
    JSON.stringify(testCase.fixture, null, 2),
  );

  // act requires a git repo with at least one commit.
  run("git", ["init", "-q"], dir);
  run("git", ["config", "user.email", "harness@test"], dir);
  run("git", ["config", "user.name", "harness"], dir);
  run("git", ["add", "-A"], dir);
  run("git", ["commit", "-q", "-m", "test fixture"], dir);
  return dir;
}

/** Extract the plan output lines (DELETE/RETAIN/SUMMARY) from act output. */
function parsePlan(output: string) {
  const deleted: string[] = [];
  const retained: string[] = [];
  const summary: Record<string, number> = {};
  for (const rawLine of output.split("\n")) {
    const line = rawLine.replace(/\r$/, "");
    const del = line.match(/DELETE (\S+) bytes=(\d+) reason=(\S+)/);
    if (del) deleted.push(del[1]!);
    const ret = line.match(/RETAIN (\S+) bytes=(\d+)/);
    if (ret) retained.push(ret[1]!);
    const sum = line.match(/SUMMARY (\w+)=(\d+)/);
    if (sum) summary[sum[1]!] = Number(sum[2]);
  }
  return { deleted: deleted.sort(), retained: retained.sort(), summary };
}

let failures = 0;
function check(label: string, cond: boolean, detail = ""): void {
  if (cond) {
    console.log(`  ✓ ${label}`);
  } else {
    failures++;
    console.log(`  ✗ ${label} ${detail}`);
  }
}

function delim(title: string): string {
  return `\n${"=".repeat(72)}\n=== ${title}\n${"=".repeat(72)}\n`;
}

// Fresh result file each run.
writeFileSync(RESULT_FILE, `act integration results\n`);

for (const testCase of CASES) {
  console.log(`\n▶ CASE: ${testCase.name}`);
  const dir = setupRepo(testCase);
  let output = "";
  let code = 1;
  try {
    const r = run("act", ["push", "--rm"], dir);
    output = r.out;
    code = r.code;
  } finally {
    appendFileSync(RESULT_FILE, delim(`CASE: ${testCase.name}`));
    appendFileSync(RESULT_FILE, `ACT EXIT CODE: ${code}\n`);
    appendFileSync(RESULT_FILE, output);
    rmSync(dir, { recursive: true, force: true });
  }

  const exp = testCase.expected;
  // 1. act exited cleanly.
  check("act exited 0", code === 0, `(got ${code})`);

  // 2. Every job reported success. The workflow has two jobs.
  const successCount = (output.match(/Job succeeded/g) ?? []).length;
  check("both jobs succeeded", successCount >= 2, `(saw ${successCount} "Job succeeded")`);

  // 3. Exact plan values.
  const plan = parsePlan(output);
  check("deleted set matches", JSON.stringify(plan.deleted) === JSON.stringify(exp.deleted),
    `expected ${JSON.stringify(exp.deleted)} got ${JSON.stringify(plan.deleted)}`);
  check("retained set matches", JSON.stringify(plan.retained) === JSON.stringify(exp.retained),
    `expected ${JSON.stringify(exp.retained)} got ${JSON.stringify(plan.retained)}`);
  check("summary.total", plan.summary.total === exp.total, `got ${plan.summary.total}`);
  check("summary.deleted", plan.summary.deleted === exp.deletedCount, `got ${plan.summary.deleted}`);
  check("summary.retained", plan.summary.retained === exp.retainedCount, `got ${plan.summary.retained}`);
  check("summary.bytesReclaimed", plan.summary.bytesReclaimed === exp.bytesReclaimed, `got ${plan.summary.bytesReclaimed}`);
  check("summary.bytesRetained", plan.summary.bytesRetained === exp.bytesRetained, `got ${plan.summary.bytesRetained}`);
}

console.log(`\n${failures === 0 ? "✅ ALL ACT CASES PASSED" : `❌ ${failures} ASSERTION(S) FAILED`}`);
console.log(`Output saved to ${RESULT_FILE}`);
process.exit(failures === 0 ? 0 : 1);

