#!/usr/bin/env bun
/**
 * Integration harness: runs the artifact-cleanup workflow through `act`
 * (nektos/act) for each test case and asserts on EXACT expected output.
 *
 * Per requirements, every test case executes through the GitHub Actions
 * pipeline (not the script directly). For each case we:
 *   1. Build an isolated temp git repo containing the project files + that
 *      case's config data (written to fixtures/active.json — the path the
 *      workflow reads by default).
 *   2. Run `act push --rm` and capture stdout+stderr.
 *   3. Append the output to act-result.txt (clearly delimited).
 *   4. Assert act exited 0, every job shows "Job succeeded", and the parsed
 *      renderReport output matches the known-good values for that config.
 *
 * Run with:  bun run act-harness.ts
 *
 * NOTE: This file is intentionally NOT named *.test.ts so that the in-CI
 * `bun test` step does not try to invoke act recursively inside act.
 */

import {
  mkdtempSync,
  writeFileSync,
  copyFileSync,
  mkdirSync,
  rmSync,
  appendFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const HERE = import.meta.dir;
const RESULT_FILE = join(HERE, "act-result.txt");
const WORKFLOW_REL = join(".github", "workflows", "artifact-cleanup-script.yml");

// Files copied into each isolated repo so the workflow can run.
const PROJECT_FILES = ["cleanup.ts", "cleanup.test.ts", "package.json", ".actrc"];

interface ExpectedPlan {
  mode: "DRY-RUN" | "EXECUTE";
  deleted: string[]; // artifact names, sorted
  retained: string[]; // artifact names, sorted
  total: number;
  deletedCount: number;
  retainedCount: number;
  bytesReclaimed: number;
  bytesRetained: number;
}

interface TestCase {
  name: string;
  /** Config object written verbatim to fixtures/active.json. */
  config: unknown;
  expected: ExpectedPlan;
}

// Each config embeds `now`, so expectations are fully deterministic.
const CASES: TestCase[] = [
  {
    name: "max-age + dry-run: old CI artifacts flagged, fresh one kept",
    config: {
      now: "2026-06-26T00:00:00Z",
      dryRun: true,
      policy: { maxAgeDays: 30 },
      artifacts: [
        { name: "old1", sizeBytes: 1000, createdAt: "2026-01-01T00:00:00Z", workflowName: "ci", workflowRunId: 1 },
        { name: "old2", sizeBytes: 1500, createdAt: "2026-03-01T00:00:00Z", workflowName: "ci", workflowRunId: 2 },
        { name: "fresh", sizeBytes: 2000, createdAt: "2026-06-25T00:00:00Z", workflowName: "ci", workflowRunId: 3 },
      ],
    },
    // old1 & old2 are >30d old -> deleted; fresh (1d) retained.
    expected: {
      mode: "DRY-RUN",
      deleted: ["old1", "old2"],
      retained: ["fresh"],
      total: 3,
      deletedCount: 2,
      retainedCount: 1,
      bytesReclaimed: 2500,
      bytesRetained: 2000,
    },
  },
  {
    name: "max-total-size + execute: oldest evicted to meet budget",
    config: {
      now: "2026-06-26T00:00:00Z",
      dryRun: false,
      policy: { maxTotalSizeBytes: 3500 },
      artifacts: [
        { name: "a", sizeBytes: 1000, createdAt: "2026-06-01T00:00:00Z", workflowName: "ci", workflowRunId: 1 },
        { name: "b", sizeBytes: 2000, createdAt: "2026-06-02T00:00:00Z", workflowName: "ci", workflowRunId: 2 },
        { name: "c", sizeBytes: 3000, createdAt: "2026-06-03T00:00:00Z", workflowName: "ci", workflowRunId: 3 },
      ],
    },
    // Total 6000 > 3500. Evict oldest first: a (->5000), b (->3000 <= 3500).
    expected: {
      mode: "EXECUTE",
      deleted: ["a", "b"],
      retained: ["c"],
      total: 3,
      deletedCount: 2,
      retainedCount: 1,
      bytesReclaimed: 3000,
      bytesRetained: 3000,
    },
  },
];

/** Run a command, returning combined output and exit code. */
function run(cmd: string, cmdArgs: string[], cwd: string): { out: string; code: number } {
  const res = spawnSync(cmd, cmdArgs, {
    cwd,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
  });
  const out = `${res.stdout ?? ""}${res.stderr ?? ""}`;
  return { out, code: res.status ?? 1 };
}

/** Build an isolated git repo for a single test case. */
function setupRepo(testCase: TestCase): string {
  const dir = mkdtempSync(join(tmpdir(), "act-artifact-"));

  for (const f of PROJECT_FILES) {
    copyFileSync(join(HERE, f), join(dir, f));
  }
  mkdirSync(join(dir, ".github", "workflows"), { recursive: true });
  copyFileSync(join(HERE, WORKFLOW_REL), join(dir, WORKFLOW_REL));

  mkdirSync(join(dir, "fixtures"), { recursive: true });
  writeFileSync(
    join(dir, "fixtures", "active.json"),
    JSON.stringify(testCase.config, null, 2),
  );

  // act requires a git repo with at least one commit.
  run("git", ["init", "-q", "-b", "master"], dir);
  run("git", ["config", "user.email", "harness@test"], dir);
  run("git", ["config", "user.name", "harness"], dir);
  run("git", ["add", "-A"], dir);
  run("git", ["commit", "-q", "-m", "test fixture"], dir);
  return dir;
}

/** Extract renderReport lines (DELETE/RETAIN/KEY=value) from act output. */
function parsePlan(output: string) {
  const deleted: string[] = [];
  const retained: string[] = [];
  const kv: Record<string, string> = {};
  for (const rawLine of output.split("\n")) {
    const line = rawLine.replace(/\r$/, "");
    const del = line.match(/DELETE (\S+) reason=(\S+) size=(\d+)/);
    if (del) deleted.push(del[1]!);
    const ret = line.match(/RETAIN (\S+) size=(\d+)/);
    if (ret) retained.push(ret[1]!);
    const m = line.match(/^([A-Z_]+)=(.+)$/);
    if (m) kv[m[1]!] = m[2]!;
  }
  return { deleted: deleted.sort(), retained: retained.sort(), kv };
}

let failures = 0;
function check(label: string, cond: boolean, detail = ""): void {
  if (cond) {
    console.log(`  ✓ ${label}`);
  } else {
    failures++;
    console.log(`  ✗ ${label} ${detail}`);
  }
}

function delim(title: string): string {
  return `\n${"=".repeat(72)}\n=== ${title}\n${"=".repeat(72)}\n`;
}

// Fresh result file each run.
writeFileSync(RESULT_FILE, `act integration results\n`);

for (const testCase of CASES) {
  console.log(`\n▶ CASE: ${testCase.name}`);
  const dir = setupRepo(testCase);
  let output = "";
  let code = 1;
  try {
    const r = run("act", ["push", "--rm"], dir);
    output = r.out;
    code = r.code;
  } finally {
    appendFileSync(RESULT_FILE, delim(`CASE: ${testCase.name}`));
    appendFileSync(RESULT_FILE, `ACT EXIT CODE: ${code}\n`);
    appendFileSync(RESULT_FILE, output);
    rmSync(dir, { recursive: true, force: true });
  }

  const exp = testCase.expected;
  // 1. act exited cleanly.
  check("act exited 0", code === 0, `(got ${code})`);

  // 2. Every job reported success. The workflow has two jobs (test + plan).
  const successCount = (output.match(/Job succeeded/g) ?? []).length;
  check("both jobs succeeded", successCount >= 2, `(saw ${successCount} "Job succeeded")`);

  // 3. Exact plan values parsed from the workflow's renderReport output.
  const plan = parsePlan(output);
  check("MODE matches", plan.kv.MODE === exp.mode, `expected ${exp.mode} got ${plan.kv.MODE}`);
  check(
    "deleted set matches",
    JSON.stringify(plan.deleted) === JSON.stringify(exp.deleted),
    `expected ${JSON.stringify(exp.deleted)} got ${JSON.stringify(plan.deleted)}`,
  );
  check(
    "retained set matches",
    JSON.stringify(plan.retained) === JSON.stringify(exp.retained),
    `expected ${JSON.stringify(exp.retained)} got ${JSON.stringify(plan.retained)}`,
  );
  check("TOTAL_ARTIFACTS", plan.kv.TOTAL_ARTIFACTS === String(exp.total), `got ${plan.kv.TOTAL_ARTIFACTS}`);
  check("DELETED_COUNT", plan.kv.DELETED_COUNT === String(exp.deletedCount), `got ${plan.kv.DELETED_COUNT}`);
  check("RETAINED_COUNT", plan.kv.RETAINED_COUNT === String(exp.retainedCount), `got ${plan.kv.RETAINED_COUNT}`);
  check("BYTES_RECLAIMED", plan.kv.BYTES_RECLAIMED === String(exp.bytesReclaimed), `got ${plan.kv.BYTES_RECLAIMED}`);
  check("BYTES_RETAINED", plan.kv.BYTES_RETAINED === String(exp.bytesRetained), `got ${plan.kv.BYTES_RETAINED}`);
}

console.log(`\n${failures === 0 ? "✅ ALL ACT CASES PASSED" : `❌ ${failures} ASSERTION(S) FAILED`}`);
console.log(`Output saved to ${RESULT_FILE}`);
process.exit(failures === 0 ? 0 : 1);

