import { describe, it, expect } from "bun:test";
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";

// Workflow structure tests. These validate the GitHub Actions workflow file's
// shape and that it references real script files. They do NOT run `act` — that
// lives in act-harness.ts. They are excluded from the in-CI `bun test`
// invocation (which targets cleanup.test.ts only) so actionlint/act are not
// required inside the runner container.

const WORKFLOW = ".github/workflows/artifact-cleanup-script.yml";

describe("workflow file — existence & references", () => {
  it("the workflow file exists", () => {
    expect(existsSync(WORKFLOW)).toBe(true);
  });

  it("references the cleanup script, which exists on disk", () => {
    const text = require("node:fs").readFileSync(WORKFLOW, "utf8") as string;
    expect(text).toContain("bun run cleanup.ts");
    expect(existsSync("cleanup.ts")).toBe(true);
  });

  it("references a default fixture that exists on disk", () => {
    expect(existsSync("fixtures/active.json")).toBe(true);
  });
});

describe("workflow file — structure", () => {
  const text = require("node:fs").readFileSync(WORKFLOW, "utf8") as string;

  it("declares the expected trigger events", () => {
    // The `on:` block should include push, pull_request, schedule, dispatch.
    expect(text).toMatch(/^on:/m);
    expect(text).toContain("push:");
    expect(text).toContain("pull_request:");
    expect(text).toContain("schedule:");
    expect(text).toContain("workflow_dispatch:");
    expect(text).toMatch(/cron:\s*'[^']+'/);
  });

  it("declares least-privilege permissions", () => {
    expect(text).toMatch(/permissions:\s*\n\s*contents:\s*read/);
  });

  it("defines both jobs with a dependency between them", () => {
    expect(text).toMatch(/^\s{2}test:/m);
    expect(text).toMatch(/^\s{2}cleanup-plan:/m);
    // cleanup-plan must wait for the unit-test job.
    expect(text).toMatch(/needs:\s*test/);
  });

  it("checks out the repo and sets up Bun in each job", () => {
    expect(text).toContain("actions/checkout@v4");
    expect(text).toContain("oven-sh/setup-bun@v2");
  });

  it("runs unit tests in the test job", () => {
    expect(text).toContain("bun test");
  });
});

describe("workflow file — actionlint", () => {
  it("passes actionlint with exit code 0", () => {
    const res = spawnSync("actionlint", [WORKFLOW], { encoding: "utf8" });
    // If actionlint is unavailable, skip gracefully rather than fail.
    if (res.error && (res.error as NodeJS.ErrnoException).code === "ENOENT") {
      console.warn("actionlint not found; skipping lint assertion.");
      return;
    }
    expect(res.stdout ?? "").toBe("");
    expect(res.status).toBe(0);
  });
});

